// Score: survival (DESIGN.md §"Score: survival"). Share of the lines a session's commit(s) added that
// `git blame -w -M -C HEAD` still attributes to those commits.

import { gitPool, type GitRunner } from "./rework.ts";

export interface Survival {
  added: number;
  surviving: number;
  /** surviving ÷ added; 1 when nothing was added (nothing to lose). */
  ratio: number;
}

const GENERATED = [
  /(^|\/)dist\//,
  /\.min\.[^/]*$/,
  /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|Cargo\.lock|poetry\.lock|Gemfile\.lock|composer\.lock|go\.sum)$/,
];

export function isGenerated(path: string): boolean {
  return GENERATED.some((re) => re.test(path));
}

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const r = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], {
    cwd: repo,
    stdout: "pipe",
    stderr: "pipe",
    maxBuffer: 256 * 1024 * 1024,
  });
  return { ok: r.exitCode === 0, out: r.stdout.toString() };
}

const SHOW = ["show", "-w", "--ignore-blank-lines", "-U0", "--no-renames", "--format="];
const BLAME = ["blame", "-w", "-M", "-C", "--line-porcelain"];

/** Added (non-blank, whitespace-insensitive) line count per non-generated file for one commit. */
function addedByFile(repo: string, sha: string): Map<string, number> {
  const res = git(repo, [...SHOW, sha]);
  if (!res.ok) throw new Error(`git show ${sha} failed in ${repo}`);
  return parseAdded(res.out);
}

function parseAdded(out: string): Map<string, number> {
  const counts = new Map<string, number>();
  let file: string | null = null;
  let inHunk = false;
  for (const line of out.split("\n")) {
    if (line.startsWith("diff --git ")) {
      file = null;
      inHunk = false;
    } else if (!inHunk && line.startsWith("+++ ")) {
      file = line === "+++ /dev/null" ? null : line.slice(6);
    } else if (line.startsWith("@@")) {
      inHunk = true;
    } else if (inHunk && file && line.startsWith("+") && line.trim().length > 1 && !isGenerated(file)) {
      counts.set(file, (counts.get(file) ?? 0) + 1);
    }
  }
  return counts;
}

// Blame cache: repo + resolved HEAD + file → line count per full commit sha.
const blameCache = new Map<string, Map<string, number>>();

function blameCounts(repo: string, head: string, file: string): Map<string, number> {
  const key = `${repo}\0${head}\0${file}`;
  const hit = blameCache.get(key);
  if (hit) return hit;
  const res = git(repo, [...BLAME, head, "--", file]);
  const counts = parseBlame(res);
  blameCache.set(key, counts);
  return counts;
}

/** A failed blame (the file is gone at HEAD) attributes nothing. */
function parseBlame(res: { ok: boolean; out: string }): Map<string, number> {
  const counts = new Map<string, number>();
  if (res.ok) {
    // Each blamed line starts with "<40-hex sha> <orig> <final> [<group size>]"; content lines start with a tab.
    for (const line of res.out.split("\n")) {
      if (/^[0-9a-f]{40} \d+ \d+/.test(line)) {
        const sha = line.slice(0, 40);
        counts.set(sha, (counts.get(sha) ?? 0) + 1);
      }
    }
  }
  return counts;
}

function resolve(repo: string, rev: string): string {
  const r = git(repo, ["rev-parse", "--verify", `${rev}^{commit}`]);
  if (!r.ok) throw new Error(`cannot resolve ${rev} in ${repo}`);
  return r.out.trim();
}

export function survival(repoPath: string, commitShas: string[], headSha: string): Survival {
  const head = resolve(repoPath, headSha);
  const shas = new Set(commitShas.map((s) => resolve(repoPath, s)));

  const added = new Map<string, number>();
  for (const sha of shas) {
    for (const [file, n] of addedByFile(repoPath, sha)) added.set(file, (added.get(file) ?? 0) + n);
  }

  return tally(added, shas, (file) => blameCounts(repoPath, head, file));
}

function tally(added: Map<string, number>, shas: Set<string>, blamed: (file: string) => Map<string, number>): Survival {
  let total = 0;
  let surviving = 0;
  for (const [file, n] of added) {
    total += n;
    const counts = blamed(file);
    let mine = 0;
    for (const sha of shas) mine += counts.get(sha) ?? 0;
    surviving += Math.min(mine, n);
  }
  return { added: total, surviving, ratio: total === 0 ? 1 : surviving / total };
}

// ---------- batch: one blame per (file, HEAD) for a whole review ----------

/** Blame line counts per `repo + HEAD + file`, shared by every session of one review. */
export type BlameCache = Map<string, Promise<Map<string, number>>>;

/**
 * `survival` for many commit sets at once, with the same results. `head` and every sha must be full
 * commit ids. Each commit's diff is read once; `git blame` runs at most once per (file, head) across
 * all sets, and through `cache` across calls. A set that cannot be scored maps to its Error.
 */
export async function survivalMany(
  repoPath: string,
  sets: string[][],
  head: string,
  run: GitRunner = gitPool(),
  cache: BlameCache = new Map(),
): Promise<(Survival | Error)[]> {
  const quoted = (args: string[]) => ["-c", "core.quotepath=off", ...args];
  const shows = new Map<string, Promise<Map<string, number>>>();
  const addedOf = (sha: string) => {
    let p = shows.get(sha);
    if (!p) {
      p = run(repoPath, quoted([...SHOW, sha])).then((res) => {
        if (!res.ok) throw new Error(`git show ${sha} failed in ${repoPath}`);
        return parseAdded(res.out);
      });
      shows.set(sha, p);
    }
    return p;
  };
  const blameOf = (file: string) => {
    const key = `${repoPath}\0${head}\0${file}`;
    let p = cache.get(key);
    if (!p) {
      p = run(repoPath, quoted([...BLAME, head, "--", file])).then(parseBlame);
      cache.set(key, p);
    }
    return p;
  };

  return Promise.all(
    sets.map(async (set) => {
      try {
        const shas = new Set(set);
        const added = new Map<string, number>();
        for (const perFile of await Promise.all([...shas].map(addedOf))) {
          for (const [file, n] of perFile) added.set(file, (added.get(file) ?? 0) + n);
        }
        const files = [...added.keys()];
        const blamed = new Map((await Promise.all(files.map(blameOf))).map((c, i) => [files[i]!, c]));
        return tally(added, shas, (file) => blamed.get(file)!);
      } catch (err) {
        return err instanceof Error ? err : new Error(String(err));
      }
    }),
  );
}
// DESIGN.md §"Score: reverted, rework". A change counts as reverted when a later commit says
// `This reverts commit <sha>`, or when at least half of its added lines are deleted within the window.

import { DEFAULT_WINDOW, trackLines, type Tracked } from "./rework.ts";

export const REVERT_SHARE = 0.5;

export function reverted(repo: string, sha: string, window: number = DEFAULT_WINDOW): boolean {
  return isReverted(trackLines(repo, sha, window));
}

/** The revert verdict from tracked lines, so one `trackMany` pass serves both rework and reverted. */
export function isReverted(t: Tracked): boolean {
  if (t.explicitRevert) return true;
  return t.added > 0 && t.matchedHuman + t.matchedAgent >= REVERT_SHARE * t.added;
}
// Outcomes table (DESIGN.md §"Score"). One row per session. Only mature sessions get metrics: the
// commit must be ≥ 5 first-parent commits and ≥ 6 h older than HEAD. Everything else is censored
// as `too_young` with null metrics (except `unattended`, which needs no commit age), and `censored` says why.

import { priceSession } from "../price/index.ts";
import type { Outcome, Session } from "../types.ts";
import { reverted } from "./revert.ts";
import { rework } from "./rework.ts";
import { survival } from "./survival.ts";

export const MATURE_MIN_COMMITS = 5;
export const MATURE_MIN_AGE_MS = 6 * 3600 * 1000;
/** Bucket for sessions whose setup is unknown (`setup_id` null). */
export const UNKNOWN_SETUP = "unknown";

/** Why a session has no metrics. `too_young`: the commit is not old enough yet. */
export type Censor = "too_young" | "no_commit" | "not_on_head";

/** An Outcome plus what aggregation needs. Cost is a spend, not a quality metric, so censored rows keep it. */
export interface ScoredOutcome extends Outcome {
  setup_id: string | null;
  commit_sha: string | null;
  /** null when the model or a price is unknown. */
  cost_usd: number | null;
  censored: Censor | null;
}

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  return { ok: p.exitCode === 0, out: p.stdout.toString().trim() };
}

function commitTimeMs(repo: string, rev: string): number {
  return Number(git(repo, ["log", "-1", "--format=%ct", rev]).out) * 1000;
}

/** Why `sha` is not mature against HEAD, or null when it is. */
export function maturity(repo: string, sha: string): Censor | null {
  if (!git(repo, ["merge-base", "--is-ancestor", sha, "HEAD"]).ok) return "not_on_head";
  const newer = Number(git(repo, ["rev-list", "--first-parent", "--count", `${sha}..HEAD`]).out);
  const age = commitTimeMs(repo, "HEAD") - commitTimeMs(repo, sha);
  return newer >= MATURE_MIN_COMMITS && age >= MATURE_MIN_AGE_MS ? null : "too_young";
}

/**
 * The session's own cost if ingest priced it, otherwise its summed tokens priced by src/price.
 * Sessions store totals, not per-request prompt sizes, so the tier uses the session's total prompt as a bound:
 * a session under 100k total is certainly short-tier; one over it is priced at the short tier and is a lower bound.
 */
export function sessionCostDetail(s: Session): { usd: number | null; lower_bound: boolean } {
  if (s.cost_usd !== null) return { usd: s.cost_usd, lower_bound: false };
  const promptTotal = s.tokens_in + s.cache_read + s.cache_write;
  const r = priceSession(s.model, {
    input: s.tokens_in,
    output: s.tokens_out,
    cache_read: s.cache_read,
    cache_write: s.cache_write,
    prompt_tokens_bound: promptTotal,
  });
  return { usd: r.usd, lower_bound: r.lower_bound === true };
}

export function sessionCost(s: Session): number | null {
  return sessionCostDetail(s).usd;
}

export function scoreSessions(repo: string, sessions: Session[]): ScoredOutcome[] {
  return sessions.map((s) => {
    const base: ScoredOutcome = {
      session_id: s.id,
      status: "too_young",
      survival: null,
      reverted: null,
      rework_human: null,
      rework_agent: null,
      // Needs only the prompt count, not commit age, so censored sessions keep it.
      unattended: Number.isFinite(s.n_user_prompts) ? s.n_user_prompts === 1 : null,
      tests_at_commit: null,
      difficulty: null,
      tercile: null,
      setup_id: s.setup_id,
      commit_sha: s.commit_sha,
      cost_usd: sessionCost(s),
      censored: "no_commit",
    };
    if (s.commit_sha === null) return base;
    const censored = maturity(repo, s.commit_sha);
    if (censored) return { ...base, censored };
    const r = rework(repo, s.commit_sha);
    return {
      ...base,
      status: "mature",
      censored: null,
      survival: survival(repo, [s.commit_sha], "HEAD").ratio,
      reverted: reverted(repo, s.commit_sha),
      rework_human: r.human,
      rework_agent: r.agent,
    };
  });
}

export interface SetupAggregate {
  setup_id: string;
  /** All sessions of the setup, mature or censored. */
  sessions: number;
  mature: number;
  too_young: number;
  /** Mature sessions only. */
  reverted: number;
  /** Sessions with a known prompt count that needed exactly one prompt, mature or not. */
  unattended: number;
  /** Sessions with a known prompt count, mature or not: the denominator of the unattended share. */
  unattended_known: number;
  survival_sum: number;
  survival_mean: number | null;
  /** Σ cost over all sessions; null when any session's cost is unknown (a partial sum would understate spend). */
  cost_usd: number | null;
  /** Sessions with a known cost. Equals `sessions` exactly when cost_usd is non-null. */
  priced_sessions: number;
  cost_unknown: number;
  /**
   * Σ cost ÷ Σ survival over mature sessions with a known cost. null when there are none, when
   * Σ survival is 0, or when any mature session's cost is unknown (a partial sum would flatter it).
   */
  cost_per_surviving_change: number | null;
}

export function aggregateBySetup(outcomes: ScoredOutcome[]): SetupAggregate[] {
  const groups = new Map<string, ScoredOutcome[]>();
  for (const o of outcomes) {
    const k = o.setup_id ?? UNKNOWN_SETUP;
    groups.set(k, [...(groups.get(k) ?? []), o]);
  }
  return [...groups.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([setup_id, rows]) => {
      const mature = rows.filter((o) => o.status === "mature");
      const known = rows.filter((o) => o.cost_usd !== null);
      const survivalSum = mature.reduce((a, o) => a + (o.survival ?? 0), 0);
      const matureCost = mature.reduce((a, o) => a + (o.cost_usd ?? 0), 0);
      const matureCostKnown = mature.length > 0 && mature.every((o) => o.cost_usd !== null);
      return {
        setup_id,
        sessions: rows.length,
        mature: mature.length,
        too_young: rows.length - mature.length,
        reverted: mature.filter((o) => o.reverted).length,
        unattended: rows.filter((o) => o.unattended).length,
        unattended_known: rows.filter((o) => o.unattended !== null).length,
        survival_sum: survivalSum,
        survival_mean: mature.length ? survivalSum / mature.length : null,
        cost_usd: known.length === rows.length ? known.reduce((a, o) => a + (o.cost_usd ?? 0), 0) : null,
        priced_sessions: known.length,
        cost_unknown: rows.length - known.length,
        cost_per_surviving_change: matureCostKnown && survivalSum > 0 ? matureCost / survivalSum : null,
      };
    });
}

/** Report shape for reports/outcomes.json. Totals follow the rules scripts/sumcheck.ts checks. */
export function outcomesReport(outcomes: ScoredOutcome[]) {
  const setups = aggregateBySetup(outcomes);
  const bySetup = (pick: (a: SetupAggregate) => number) => Object.fromEntries(setups.map((a) => [a.setup_id, pick(a)]));
  const priced = setups.filter((a) => a.cost_usd !== null);
  return {
    sessions: { total: outcomes.length, by_setup: bySetup((a) => a.sessions) },
    mature: { total: outcomes.filter((o) => o.status === "mature").length, by_setup: bySetup((a) => a.mature) },
    too_young: { total: outcomes.filter((o) => o.status === "too_young").length, by_setup: bySetup((a) => a.too_young) },
    reverted: { total: outcomes.filter((o) => o.reverted).length, by_setup: bySetup((a) => a.reverted) },
    unattended: { total: outcomes.filter((o) => o.unattended).length, by_setup: bySetup((a) => a.unattended) },
    // Only setups with a known cost appear here; cost_unknown counts the sessions left out.
    cost_total_usd: priced.reduce((s, a) => s + (a.cost_usd ?? 0), 0),
    cost_by_setup: Object.fromEntries(priced.map((a) => [a.setup_id, a.cost_usd as number])),
    cost_unknown: { total: outcomes.filter((o) => o.cost_usd === null).length, by_setup: bySetup((a) => a.cost_unknown) },
    setups,
    outcomes,
  };
}

export interface GitResult {
  ok: boolean;
  out: string;
  err: string;
}

/** Runs `git <args>` in `repo`. Injectable so tests can count the commands a review spawns. */
export type GitRunner = (repo: string, args: string[], stdin?: string) => Promise<GitResult>;

/** Git processes a review runs at once. */
export const GIT_PARALLEL = 8;

/** Spawns one git process and collects its output. */
export const spawnGit: GitRunner = async (repo, args, stdin) => {
  const p = Bun.spawn(["git", ...args], { cwd: repo, stdin: stdin === undefined ? "ignore" : "pipe", stdout: "pipe", stderr: "pipe" });
  if (stdin !== undefined && p.stdin) {
    p.stdin.write(stdin);
    p.stdin.end();
  }
  const [out, err, code] = await Promise.all([new Response(p.stdout).text(), new Response(p.stderr).text(), p.exited]);
  return { ok: code === 0, out, err };
};

/** Wraps `run` so that at most `limit` commands are in flight. */
export function gitPool(run: GitRunner = spawnGit, limit: number = GIT_PARALLEL): GitRunner {
  let active = 0;
  const waiting: (() => void)[] = [];
  return async (repo, args, stdin) => {
    if (active >= limit) await new Promise<void>((r) => waiting.push(r));
    active++;
    try {
      return await run(repo, args, stdin);
    } finally {
      active--;
      waiting.shift()?.();
    }
  };
}

/** Like `git` below, through a runner. */
async function gitAsync(run: GitRunner, repo: string, args: string[], stdin?: string): Promise<string> {
  const r = await run(repo, args, stdin);
  if (!r.ok) throw new Error(`git ${args.join(" ")} failed: ${r.err.trim()}`);
  return r.out;
}

